import copy
import hashlib
import json

STATUS_ORDER = {"DRAFT": 0, "SUBMITTED": 1, "AUTHORISED": 2}
# The highest Xero status the agent may set, by the client's approval route. Any other route: Draft only.
MAX_STATUS = {"bookkeeper": "AUTHORISED", "hj_reviewer": "AUTHORISED", "client_each_bill": "SUBMITTED"}


class Refused(Exception):
    def __init__(self, code, reason):
        super().__init__(reason)
        self.code = code
        self.reason = reason


def as_data(value):
    if isinstance(value, str):
        try:
            return json.loads(value)
        except Exception:
            return value
    return value


def tidy(value):
    """The same value however it was written: 100 and 100.0 compare equal."""
    value = as_data(value)
    if isinstance(value, dict):
        return {str(k): tidy(v) for k, v in value.items()}
    if isinstance(value, list):
        return [tidy(v) for v in value]
    if isinstance(value, float) and value.is_integer():
        return int(value)
    return value


def approval_digest(action, tenant, invoice, invoice_id, patch):
    body = {"action": action, "xero_tenant_id": tenant}
    if action == "create":
        body["invoice"] = invoice
    else:
        body["invoice_id"] = invoice_id
        body["patch"] = patch
    text = json.dumps(tidy(body), sort_keys=True, separators=(",", ":"), ensure_ascii=False)
    return hashlib.sha256(text.encode("utf-8")).hexdigest()[:12]


def approval_from_params():
    action = str(params.get("action") or "").strip().lower()
    tenant = str(params.get("xero_tenant_id") or "").strip()
    invoice = tidy(params.get("invoice")) if action == "create" else None
    invoice_id = str(params.get("invoice_id") or "").strip() if action == "update" else ""
    patch = tidy(params.get("patch")) if action == "update" else None
    return action, tenant, invoice, invoice_id, patch


def first_invoice(value):
    value = as_data(value)
    if isinstance(value, dict):
        rows = value.get("Invoices") or value.get("invoices")
        if isinstance(rows, list):
            return rows[0] if rows and isinstance(rows[0], dict) else {}
        if value.get("InvoiceID"):
            return value
    if isinstance(value, list) and value and isinstance(value[0], dict):
        return value[0]
    return {}


def all_invoices(value):
    value = as_data(value)
    if isinstance(value, dict):
        rows = value.get("Invoices") or value.get("invoices") or []
        return [r for r in rows if isinstance(r, dict)]
    if isinstance(value, list):
        return [r for r in value if isinstance(r, dict)]
    return []


def amount(value):
    try:
        return round(float(value), 4)
    except Exception:
        return None


def get_record(type_slug, record_id):
    if not record_id:
        return {}
    row = as_data(api.records.get(type_slug=type_slug, record_id=record_id))
    if isinstance(row, dict) and isinstance(row.get("record"), dict):
        row = row["record"]
    return row if isinstance(row, dict) else {}


def field(row, key):
    data = row.get("data") or row.get("fields") or {}
    return data.get(key, row.get(key))


def client_id_of(row):
    links = row.get("links") if isinstance(row.get("links"), dict) else {}
    found = links.get("client") or field(row, "client")
    if isinstance(found, list):
        found = found[0] if found else ""
    if isinstance(found, dict):
        found = found.get("id") or found.get("record_id") or ""
    return str(found or "")


def bill_context(record_id, tenant):
    """The AP bill row, its client's approval route, and a check that the Xero organisation is that client's."""
    row = get_record("ap_bill", record_id)
    if not row:
        raise Refused("bad_input", "The AP bill row couldn't be read.")
    client = get_record("client", client_id_of(row))
    route = str(field(row, "approval_route") or field(client, "ap_approval_route") or "").strip().lower()
    given = str(params.get("route") or "").strip().lower()
    if given and given != route:
        raise Refused("route", f"The route given ({given}) isn't this client's route ({route or 'none'}).")
    row_tenant = str(field(row, "xero_tenant_id") or "").strip()
    client_tenant = str(field(client, "ap_xero_tenant_id") or "").strip()
    if (row_tenant and row_tenant != tenant) or (client_tenant and client_tenant != tenant):
        raise Refused("tenant", "That Xero organisation isn't the one this bill's client uses.")
    return row, route


def same_supplier(bill, contact):
    theirs = bill.get("Contact") or {}
    if contact.get("ContactID") and theirs.get("ContactID"):
        return contact.get("ContactID") == theirs.get("ContactID")
    mine = str(contact.get("Name") or "").strip().lower()
    return bool(mine) and mine == str(theirs.get("Name") or "").strip().lower()


def in_job():
    return str((trigger or {}).get("kind") or "") == "process"

MODE = "internal"  # "reviewer" for 'approve in Xero'; "internal" for 'approve in Xero after internal review'
CREATE_KEYS = {"Type", "Status", "Contact", "Date", "DueDate", "InvoiceNumber", "Reference", "CurrencyCode", "LineAmountTypes", "LineItems"}
CREATE_LINE_KEYS = {"Description", "Quantity", "UnitAmount", "LineAmount", "AccountCode", "TaxType", "Tracking"}
PATCH_KEYS = {"Status", "DueDate", "LineAmountTypes", "LineItems"}
PATCH_LINE_KEYS = {"LineItemID", "Description", "Quantity", "UnitAmount", "LineAmount", "AccountCode", "TaxType", "Tracking"}
AMOUNT_KEYS = ("Quantity", "UnitAmount", "LineAmount")


def find_same(tenant, number, contact):
    found = api.connectors.invoke(server="xero-accounting", tool="list_invoices", args={"xero_tenant_id": tenant, "invoiceNumbers": number, "where": 'Type=="ACCPAY"'})
    live = [b for b in all_invoices(found) if b.get("Status") not in ("DELETED", "VOIDED") and same_supplier(b, contact)]
    return live[0] if live else None


def claim_once(record_id, row, digest):
    """A replayed run carries the same run and step as the approved one, so it is refused here."""
    claim = f"{(trigger or {}).get('runId')}:{(trigger or {}).get('stepKey')}:{digest}"
    claims = [c for c in str(field(row, "xero_write_claims") or "").splitlines() if c.strip()]
    if claim in claims:
        raise Refused("replayed", "This approved run has already been carried out once.")
    api.records.update(type_slug="ap_bill", record_id=record_id, record={"data": {"xero_write_claims": "\n".join(claims[-50:] + [claim])}})


def create(record_id, row, route, tenant, bill, digest):
    if field(row, "xero_bill_id"):
        raise Refused("already_entered", f"This AP bill is already in Xero ({field(row, 'xero_bill_id')}).")
    if not isinstance(bill, dict) or not bill:
        raise Refused("bad_input", "The bill to create is missing.")
    extra = sorted(set(bill) - CREATE_KEYS)
    if extra:
        raise Refused("bad_input", "These can't be sent when creating a bill: " + ", ".join(extra) + ".")
    if bill.get("Type") != "ACCPAY":
        raise Refused("bad_input", "Only supplier bills (Type ACCPAY) can be created.")
    status = bill.get("Status")
    if status not in STATUS_ORDER:
        raise Refused("bad_input", "The status must be DRAFT, SUBMITTED or AUTHORISED.")
    cap = MAX_STATUS.get(route, "DRAFT")
    if STATUS_ORDER[status] > STATUS_ORDER[cap]:
        raise Refused("route", f"For this client's route ({route or 'none'}) a new bill can be at most {cap}.")
    contact = bill.get("Contact")
    if not isinstance(contact, dict) or set(contact) - {"ContactID", "Name"} or not (contact.get("ContactID") or contact.get("Name")):
        raise Refused("bad_input", "The supplier must be given as a ContactID or a Name.")
    lines = bill.get("LineItems")
    if not isinstance(lines, list) or not lines or any(not isinstance(l, dict) or set(l) - CREATE_LINE_KEYS for l in lines):
        raise Refused("bad_input", "Each line may only have Description, Quantity, UnitAmount, LineAmount, AccountCode, TaxType and Tracking.")
    number = str(bill.get("InvoiceNumber") or "").strip()
    if not number:
        raise Refused("bad_input", "A bill needs its invoice number.")
    same = find_same(tenant, number, contact)
    if same:
        raise Refused("duplicate", f"Xero already has bill {number} from this supplier ({same.get('InvoiceID')}, {same.get('Status')}).")
    claim_once(record_id, row, digest)
    try:
        written = first_invoice(api.connectors.invoke(server="xero-accounting", tool="create_invoice", args={"xero_tenant_id": tenant, "invoice": bill}))
    except Exception:
        # The answer may have been lost after Xero created the bill: look before giving up.
        written = find_same(tenant, number, contact)
        if not written:
            raise
    return written, ""


def update(record_id, row, route, tenant, bill_id, patch, digest):
    if route == "approved_upstream":
        raise Refused("route", "This client approves bills before Xero (Dext, Restock or ApprovalMax), so the agent never changes them.")
    if not bill_id or not isinstance(patch, dict) or not patch:
        raise Refused("nothing_to_change", "There is nothing to change on this bill.")
    row_bill = str(field(row, "xero_bill_id") or "")
    if row_bill and row_bill != bill_id:
        raise Refused("bad_input", "That InvoiceID isn't this AP bill's bill in Xero.")
    extra = sorted(set(patch) - PATCH_KEYS)
    if extra:
        raise Refused("bad_input", "These can't be changed here: " + ", ".join(extra) + ".")
    current = first_invoice(api.connectors.invoke(server="xero-accounting", tool="get_invoice", args={"xero_tenant_id": tenant, "invoiceId": bill_id}))
    if not current or current.get("Type") != "ACCPAY":
        raise Refused("bad_input", "The bill couldn't be read from Xero as a supplier bill.")
    now = str(current.get("Status") or "")
    if now not in STATUS_ORDER:
        raise Refused("handled_in_xero", f"The bill is {now or 'in an unknown status'} in Xero now.")
    expected = str(params.get("expected_updated_utc") or "").strip()
    if not expected or str(current.get("UpdatedDateUTC") or "") != expected:
        raise Refused("changed_in_xero", "The bill has changed in Xero since it was checked.")
    if "Status" in patch:
        want = patch["Status"]
        if want not in STATUS_ORDER:
            raise Refused("bad_input", "The status must be DRAFT, SUBMITTED or AUTHORISED.")
        cap = MAX_STATUS.get(route)
        if not cap:
            raise Refused("route", f"For this client's route ({route or 'none'}) the agent doesn't change a bill's status.")
        if STATUS_ORDER[want] > STATUS_ORDER[cap]:
            raise Refused("route", f"For this client's route ({route}) a bill can be at most {cap}.")
        if STATUS_ORDER[want] < STATUS_ORDER[now]:
            raise Refused("bad_input", f"A bill is never moved back from {now} to {want}.")
    if "LineAmountTypes" in patch and patch["LineAmountTypes"] != current.get("LineAmountTypes"):
        raise Refused("amounts", "Changing whether amounts include GST changes the total. A person does that in Xero.")
    send = copy.deepcopy(patch)
    if "LineItems" in send:
        lines = send["LineItems"]
        existing = {str(li.get("LineItemID")): li for li in (current.get("LineItems") or []) if isinstance(li, dict)}
        ids = [str(l.get("LineItemID")) for l in lines if isinstance(l, dict)] if isinstance(lines, list) else []
        if not ids or len(ids) != len(lines) or len(set(ids)) != len(ids) or set(ids) != set(existing):
            raise Refused("bad_input", "Send every line of the bill once, with its LineItemID, and no new lines.")
        for line in lines:
            if set(line) - PATCH_LINE_KEYS:
                raise Refused("bad_input", "A line may only change its description, account, tax code and tracking.")
            old = existing[str(line.get("LineItemID"))]
            for key in AMOUNT_KEYS:
                if key in line and amount(line.get(key)) != amount(old.get(key)):
                    raise Refused("amounts", f"Amounts are never changed here: {key} on a line differs from Xero.")
                if key in old:
                    line[key] = old[key]
    claim_once(record_id, row, digest)
    written = first_invoice(api.connectors.invoke(server="xero-accounting", tool="update_invoice", args={"xero_tenant_id": tenant, "invoiceId": bill_id, "patch": send}))
    if not written.get("InvoiceID"):
        written = dict(written, InvoiceID=bill_id)
    note = ""
    before, after = amount(current.get("Total")), amount(written.get("Total"))
    if before is not None and after is not None and before != after:
        note = f"Xero's total changed from {before} to {after} (a tax code change)."
    return written, note


def main():
    action, tenant, bill, bill_id, patch = approval_from_params()
    record_id = str(params.get("bill_record_id") or "").strip()
    if action not in ("create", "update"):
        raise Refused("bad_input", 'action must be "create" or "update".')
    if not tenant or not record_id:
        raise Refused("bad_input", "The Xero organisation ID and the AP bill row are both needed.")
    digest = approval_digest(action, tenant, bill, bill_id, patch)
    if str(params.get("sheet_digest") or "").strip() != digest:
        raise Refused("sheet_mismatch", "These values aren't the ones on the review sheet. Rebuild the sheet and ask again.")
    row, route = bill_context(record_id, tenant)
    if MODE == "reviewer" and route == "hj_reviewer":
        raise Refused("route", "This client's bills go to the bookkeeper and then an internal reviewer.")
    if MODE == "internal":
        if route != "hj_reviewer":
            raise Refused("route", "Only bills for clients on the internal review route go to internal review.")
        if str(field(row, "internal_review_digest") or "") != digest:
            raise Refused("not_sent_by_bookkeeper", "The bookkeeper hasn't sent these exact values to internal review.")
    if action == "create":
        written, note = create(record_id, row, route, tenant, bill, digest)
    else:
        written, note = update(record_id, row, route, tenant, bill_id, patch, digest)
    # From here on Xero has changed: never raise, so nothing tries to write it again.
    done = {"xero_bill_id": str(written.get("InvoiceID") or bill_id)}
    if MODE == "internal":
        done["internal_review_digest"] = ""
    try:
        api.records.update(type_slug="ap_bill", record_id=record_id, record={"data": done})
    except Exception as err:
        note = (note + " " if note else "") + f"Xero was updated, but the AP bill row couldn't be: {err}"
    return written, note, route


written_ok = False
refused = ""
invoice_id = ""
status = ""
invoice_number = ""
problems = ""
result = ""
if not in_job():
    refused = "not_in_job"
    result = "Not run: only a Bookkeeping AP job can run this, after a person approves it. Nothing was sent to Xero."
else:
    try:
        bill_written, problems, used_route = main()
        written_ok = True
        invoice_id = str(bill_written.get("InvoiceID") or "")
        status = str(bill_written.get("Status") or "")
        invoice_number = str(bill_written.get("InvoiceNumber") or "")
        result = f"Xero now has bill {invoice_number or invoice_id}" + (f" as {status}" if status else "") + f" (route {used_route or 'none'})."
    except Refused as no:
        refused = f"{no.code}: {no.reason}"
        result = "Nothing was sent to Xero. " + no.reason
written = written_ok
